window.GENERATED_MODULES.push(.../*__DATA_START__*/[{"id":"gen-lang-sa-sanskrit-sectional-test-mtsa4hgc","subject":"lang-sa","day":62,"level":1,"title":"Sanskrit Language & Literature","hi":"संस्कृत भाषा एवं साहित्य","concepts":[{"title":"Introduction to Sanskrit Literature and Grammar","title_hi":"संस्कृत साहित्य एवं व्याकरण का परिचय","simple":"Sanskrit is an ancient language of India, and we learn about its famous books, poets, and grammar rules.","simple_hi":"संस्कृत भारत की प्राचीन भाषा है, और हम इसकी प्रसिद्ध पुस्तकों, कवियों और व्याकरण के नियमों के बारे में सीखते हैं।","intro":"","points":["संस्कृत विश्व की सबसे प्राचीन भाषाओं में से एक है, जिसे 'देवभाषा' भी कहा जाता है। / Sanskrit is one of the oldest languages, also called 'Devabhasha'.","वेद, रामायण, महाभारत जैसे महान ग्रंथ संस्कृत में लिखे गए हैं। / The Vedas, Ramayana, Mahabharata are written in Sanskrit.","पाणिनि ने 'अष्टाध्यायी' नामक व्याकरण ग्रंथ लिखा। / Panini wrote the grammar book 'Ashtadhyayi'.","कालिदास महान कवि थे, उन्होंने 'अभिज्ञानशाकुन्तलम्' लिखा। / Kalidasa was a great poet, he wrote 'Abhijnanasakuntalam'.","संस्कृत वर्णमाला में ५० वर्ण होते हैं। / Sanskrit alphabet has 50 letters.","संस्कृत भारत की शास्त्रीय भाषा है। / Sanskrit is a classical language of India."],"example":"जैसे हम हिंदी में 'राम' कहते हैं, वैसे ही संस्कृत में भी 'राम' शब्द है। संस्कृत व्याकरण में संज्ञा के तीन लिंग होते हैं - पुल्लिंग, स्त्रीलिंग, नपुंसकलिंग। जैसे 'बालक' (पुल्लिंग), 'बालिका' (स्त्रीलिंग), 'फल' (नपुंसकलिंग)। / Just as we say 'Ram' in Hindi, in Sanskrit also 'Rama' is a word. In Sanskrit grammar, nouns have three genders - masculine, feminine, neuter. For example, 'balaka' (masculine), 'balika' (feminine), 'phala' (neuter).","trick":"याद रखें: 'पाणिनि ने पाणि (हाथ) से अष्टाध्यायी लिखी' - पाणिनि का नाम 'पाणि' (हाथ) से जुड़ा है, और उन्होंने 8 अध्यायों में व्याकरण लिखा। / Remember: 'Panini wrote Ashtadhyayi with his hand (pani)' - Panini's name is linked to 'pani' (hand), and he wrote grammar in 8 chapters.","deep":{"title":"Deep Dive","title_hi":"गहन अध्ययन","body":"संस्कृत साहित्य का इतिहास वैदिक काल से आरम्भ होता है। वेद चार हैं - ऋग्वेद, यजुर्वेद, सामवेद, अथर्ववेद। रामायण के रचयिता वाल्मीकि हैं, जिन्हें 'आदिकवि' कहा जाता है। महाभारत के रचयिता वेदव्यास हैं। कालिदास को 'कविकुलगुरु' कहा जाता है। व्याकरण में पाणिनि का स्थान सर्वोपरि है, उन्होंने 3998 सूत्रों में संस्कृत व्याकरण का विधिवत वर्णन किया। परीक्षा में प्रायः इन्हीं तथ्यों पर प्रश्न पूछे जाते हैं। / The history of Sanskrit literature begins from the Vedic period. There are four Vedas - Rigveda, Yajurveda, Samaveda, Atharvaveda. Valmiki is the author of Ramayana, known as 'Adikavi'. Vedavyasa is the author of Mahabharata. Kalidasa is called 'Kavikulaguru'. In grammar, Panini is supreme; he described Sanskrit grammar in 3998 sutras. Questions in exams are often based on these facts.","body_hi":"संस्कृत साहित्य का इतिहास वैदिक काल से आरम्भ होता है। वेद चार हैं - ऋग्वेद, यजुर्वेद, सामवेद, अथर्ववेद। रामायण के रचयिता वाल्मीकि हैं, जिन्हें 'आदिकवि' कहा जाता है। महाभारत के रचयिता वेदव्यास हैं। कालिदास को 'कविकुलगुरु' कहा जाता है। व्याकरण में पाणिनि का स्थान सर्वोपरि है, उन्होंने 3998 सूत्रों में संस्कृत व्याकरण का विधिवत वर्णन किया। परीक्षा में प्रायः इन्हीं तथ्यों पर प्रश्न पूछे जाते हैं। / The history of Sanskrit literature begins from the Vedic period. There are four Vedas - Rigveda, Yajurveda, Samaveda, Atharvaveda. Valmiki is the author of Ramayana, known as 'Adikavi'. Vedavyasa is the author of Mahabharata. Kalidasa is called 'Kavikulaguru'. In grammar, Panini is supreme; he described Sanskrit grammar in 3998 sutras. Questions in exams are often based on these facts."}}],"questions":[{"q":"Who is the author of 'Ashtadhyayi'?","q_hi":"'अष्टाध्यायी' के रचयिता कौन हैं?","o":["Kalidasa","Panini","Valmiki","Vedavyasa"],"o_hi":["कालिदास","पाणिनि","वाल्मीकि","वेदव्यास"],"a":1,"exp":"Panini wrote the Ashtadhyayi, a foundational text of Sanskrit grammar.","exp_hi":"पाणिनि ने अष्टाध्यायी की रचना की, जो संस्कृत व्याकरण का आधारभूत ग्रंथ है।","why":["कालिदास एक महान कवि थे, उन्होंने नाटक और काव्य लिखे, व्याकरण नहीं।","वाल्मीकि ने रामायण की रचना की, वे व्याकरणाचार्य नहीं थे।","वेदव्यास ने महाभारत की रचना की, व्याकरण ग्रंथ नहीं लिखा।"],"topic":"Sanskrit Literature","level":1,"mode":"standard"},{"q":"Which of the following is a play written by Kalidasa?","q_hi":"निम्नलिखित में से कौन सा कालिदास द्वारा लिखित नाटक है?","o":["Raghuvamsa","Meghaduta","Abhijnanasakuntalam","Kumarasambhava"],"o_hi":["रघुवंश","मेघदूत","अभिज्ञानशाकुन्तलम्","कुमारसंभव"],"a":2,"exp":"Abhijnanasakuntalam is a famous play (drama) by Kalidasa, while the others are poems.","exp_hi":"अभिज्ञानशाकुन्तलम् कालिदास द्वारा रचित प्रसिद्ध नाटक है, जबकि अन्य काव्य हैं।","why":["रघुवंश एक महाकाव्य है, नाटक नहीं।","मेघदूत एक खण्डकाव्य है, नाटक नहीं।","कुमारसंभव एक महाकाव्य है, नाटक नहीं।"],"topic":"Sanskrit Literature","level":1,"mode":"standard"},{"q":"Who is known as 'Adikavi' (the first poet) in Sanskrit literature?","q_hi":"संस्कृत साहित्य में 'आदिकवि' किसे कहा जाता है?","o":["Kalidasa","Tulsidas","Valmiki","Bhasa"],"o_hi":["कालिदास","तुलसीदास","वाल्मीकि","भास"],"a":2,"exp":"Valmiki is revered as the Adikavi for composing the Ramayana, the first epic poem.","exp_hi":"वाल्मीकि को रामायण की रचना के लिए आदिकवि कहा जाता है, जो पहला महाकाव्य है।","why":["कालिदास को 'कविकुलगुरु' कहा जाता है, आदिकवि नहीं।","तुलसीदास हिंदी के कवि थे, संस्कृत के नहीं।","भास एक नाटककार थे, आदिकवि नहीं।"],"topic":"Sanskrit Literature","level":1,"mode":"standard"},{"q":"Which of the following is the correct order of the four Vedas?","q_hi":"चार वेदों का सही क्रम निम्नलिखित में से कौन सा है?","o":["Rigveda, Yajurveda, Samaveda, Atharvaveda","Samaveda, Rigveda, Yajurveda, Atharvaveda","Rigveda, Samaveda, Yajurveda, Atharvaveda","Yajurveda, Rigveda, Samaveda, Atharvaveda"],"o_hi":["ऋग्वेद, यजुर्वेद, सामवेद, अथर्ववेद","सामवेद, ऋग्वेद, यजुर्वेद, अथर्ववेद","ऋग्वेद, सामवेद, यजुर्वेद, अथर्ववेद","यजुर्वेद, ऋग्वेद, सामवेद, अथर्ववेद"],"a":0,"exp":"The traditional order is Rigveda, Yajurveda, Samaveda, Atharvaveda.","exp_hi":"पारंपरिक क्रम है ऋग्वेद, यजुर्वेद, सामवेद, अथर्ववेद।","why":["सामवेद को बाद में रखा जाता है, यह क्रम गलत है।","सामवेद को दूसरे स्थान पर रखना गलत है।","यजुर्वेद को पहले रखना गलत है।"],"topic":"Sanskrit Literature","level":1,"mode":"standard"},{"q":"In Sanskrit grammar, the word 'बालक' (boy) is in which gender?","q_hi":"संस्कृत व्याकरण में 'बालक' शब्द किस लिंग में है?","o":["Feminine","Masculine","Neuter","Common"],"o_hi":["स्त्रीलिंग","पुल्लिंग","नपुंसकलिंग","उभयलिंग"],"a":1,"exp":"'बालक' refers to a male child, hence it is masculine gender (पुल्लिंग).","exp_hi":"'बालक' पुरुष बच्चे के लिए है, इसलिए यह पुल्लिंग है।","why":["स्त्रीलिंग के लिए 'बालिका' शब्द होता है।","नपुंसकलिंग के लिए 'बाल' शब्द होता है।","संस्कृत में उभयलिंग की अवधारणा नहीं है।"],"topic":"Sanskrit Grammar","level":1,"mode":"standard"},{"q":"Which of the following is NOT a work of Kalidasa?","q_hi":"निम्नलिखित में से कौन सी कृति कालिदास की नहीं है?","o":["Raghuvamsa","Meghaduta","Kumarasambhava","Mricchakatika"],"o_hi":["रघुवंश","मेघदूत","कुमारसंभव","मृच्छकटिका"],"a":3,"exp":"Mricchakatika is written by Shudraka, not Kalidasa.","exp_hi":"मृच्छकटिका शूद्रक द्वारा लिखी गई है, कालिदास द्वारा नहीं।","why":["रघुवंश कालिदास का महाकाव्य है।","मेघदूत कालिदास का खण्डकाव्य है।","कुमारसंभव कालिदास का महाकाव्य है।"],"topic":"Sanskrit Literature","level":2,"mode":"standard"},{"q":"Who is known as the first poet (Adi Kavi) of Sanskrit literature?","q_hi":"संस्कृत साहित्य के प्रथम कवि (आदि कवि) कौन माने जाते हैं?","o":["Kalidasa","Valmiki","Vyasa","Bharavi"],"o_hi":["कालिदास","वाल्मीकि","व्यास","भारवि"],"a":1,"exp":"Valmiki is called Adi Kavi because he composed the Ramayana, the first Sanskrit epic (Adi Kavya). The shloka 'मा निषाद प्रतिष्ठां त्वम्...' was his first verse, born from compassion.","exp_hi":"वाल्मीकि को आदि कवि कहा जाता है क्योंकि उन्होंने रामायण की रचना की, जो प्रथम संस्कृत महाकाव्य (आदि काव्य) है। 'मा निषाद प्रतिष्ठां त्वम्...' उनका प्रथम श्लोक था, जो करुणा से उत्पन्न हुआ।","why":["कालिदास महान कवि थे, परन्तु आदि कवि नहीं; वे वाल्मीकि के बाद हुए।","व्यास ने महाभारत की रचना की, पर उन्हें आदि कवि नहीं कहा जाता।","भारवि ने किरातार्जुनीयम् लिखा, वे आदि कवि नहीं हैं।"],"topic":"Sanskrit literature - Adi Kavi","level":1,"mode":"standard"},{"q":"Which of the following is NOT a work of Kalidasa?","q_hi":"निम्नलिखित में से कौन-सी रचना कालिदास की नहीं है?","o":["Abhijnanashakuntalam","Meghadutam","Raghuvamsham","Kiratarjuniyam"],"o_hi":["अभिज्ञानशाकुन्तलम्","मेघदूतम्","रघुवंशम्","किरातार्जुनीयम्"],"a":3,"exp":"Kiratarjuniyam was written by Bharavi, not Kalidasa. Kalidasa's works include Abhijnanashakuntalam, Meghadutam, Raghuvamsham, Kumarasambhavam, Malavikagnimitram and Vikramorvashiyam.","exp_hi":"किरातार्जुनीयम् भारवि की रचना है, कालिदास की नहीं। कालिदास की कृतियों में अभिज्ञानशाकुन्तलम्, मेघदूतम्, रघुवंशम्, कुमारसम्भवम्, मालविकाग्निमित्रम् और विक्रमोर्वशीयम् सम्मिलित हैं।","why":["अभिज्ञानशाकुन्तलम् कालिदास का प्रसिद्ध नाटक है।","मेघदूतम् कालिदास की खण्डकाव्य रचना है।","रघुवंशम् कालिदास का महाकाव्य है।"],"topic":"Sanskrit literature - Kalidasa","level":2,"mode":"standard"},{"q":"In Sanskrit grammar, what is the meaning of the term 'सन्धि' (Sandhi)?","q_hi":"संस्कृत व्याकरण में 'सन्धि' शब्द का क्या अर्थ है?","o":["Combination of two words","Separation of words","Change of gender","Change of tense"],"o_hi":["दो शब्दों का मेल","शब्दों का अलगाव","लिंग परिवर्तन","काल परिवर्तन"],"a":0,"exp":"Sandhi means 'joining' — the phonetic combination of two adjacent sounds or words, e.g., विद्या + आलयः = विद्यालयः.","exp_hi":"सन्धि का अर्थ है 'मेल' — दो निकटवर्ती ध्वनियों या शब्दों का ध्वन्यात्मक संयोजन, जैसे विद्या + आलयः = विद्यालयः।","why":["शब्दों का अलगाव 'सन्धि-विच्छेद' कहलाता है, सन्धि नहीं।","लिंग परिवर्तन व्याकरण का भिन्न विषय है, सन्धि से सम्बन्धित नहीं।","काल परिवर्तन क्रिया से सम्बन्धित है, सन्धि से नहीं।"],"topic":"Sanskrit grammar - Sandhi","level":1,"mode":"standard"},{"q":"Which Sanskrit play is considered the first fully developed Sanskrit drama?","q_hi":"कौन-सा संस्कृत नाटक प्रथम पूर्ण विकसित संस्कृत नाटक माना जाता है?","o":["Mrichchhakatika","Abhijnanashakuntalam","Mudrarakshasa","Swapnavasavadattam"],"o_hi":["मृच्छकटिकम्","अभिज्ञानशाकुन्तलम्","मुद्राराक्षसम्","स्वप्नवासवदत्तम्"],"a":3,"exp":"Swapnavasavadattam by Bhasa is considered the first fully developed Sanskrit drama, known for its plot and characterization.","exp_hi":"भास का स्वप्नवासवदत्तम् प्रथम पूर्ण विकसित संस्कृत नाटक माना जाता है, जो अपनी कथावस्तु और चरित्र-चित्रण के लिए प्रसिद्ध है।","why":["मृच्छकटिकम् शूद्रक का नाटक है, पर प्रथम पूर्ण विकसित नाटक नहीं माना जाता।","अभिज्ञानशाकुन्तलम् कालिदास का उत्कृष्ट नाटक है, पर प्रथम नहीं।","मुद्राराक्षसम् विशाखदत्त का ऐतिहासिक नाटक है, प्रथम नहीं।"],"topic":"Sanskrit drama - Bhasa","level":3,"mode":"standard"},{"q":"What is the meaning of the Sanskrit proverb 'अहं ब्रह्मास्मि'?","q_hi":"संस्कृत सूक्ति 'अहं ब्रह्मास्मि' का क्या अर्थ है?","o":["I am the servant","I am Brahman","I am the world","I am the body"],"o_hi":["मैं सेवक हूँ","मैं ब्रह्म हूँ","मैं संसार हूँ","मैं शरीर हूँ"],"a":1,"exp":"'अहं ब्रह्मास्मि' is a Mahavakya from the Brihadaranyaka Upanishad meaning 'I am Brahman' — the individual self is identical with the supreme reality.","exp_hi":"'अहं ब्रह्मास्मि' बृहदारण्यक उपनिषद् का महावाक्य है, जिसका अर्थ है 'मैं ब्रह्म हूँ' — व्यक्तिगत आत्मा परम सत्य के समान है।","why":["'मैं सेवक हूँ' का संस्कृत 'अहं दासः अस्मि' होता है।","'मैं संसार हूँ' का संस्कृत 'अहं संसारः अस्मि' होता है।","'मैं शरीर हूँ' का संस्कृत 'अहं शरीरम् अस्मि' होता है।"],"topic":"Sanskrit literature - Upanishads","level":2,"mode":"standard"},{"q":"Which of the following pairs is correctly matched?","q_hi":"निम्नलिखित में से कौन-सा युग्म सही सुमेलित है?","o":["Bhavabhuti – Malatimadhava","Banabhatta – Kadambari","Sudraka – Mrichchhakatika","All of the above"],"o_hi":["भवभूति – मालतीमाधवम्","बाणभट्ट – कादम्बरी","शूद्रक – मृच्छकटिकम्","उपरोक्त सभी"],"a":3,"exp":"All pairs are correct: Bhavabhuti wrote Malatimadhava, Banabhatta wrote Kadambari, and Sudraka wrote Mrichchhakatika.","exp_hi":"सभी युग्म सही हैं: भवभूति ने मालतीमाधवम् लिखा, बाणभट्ट ने कादम्बरी लिखी, और शूद्रक ने मृच्छकटिकम् लिखा।","why":["भवभूति – मालतीमाधवम् सही है, अतः केवल यह विकल्प अपूर्ण है।","बाणभट्ट – कादम्बरी सही है, अतः केवल यह विकल्प अपूर्ण है।","शूद्रक – मृच्छकटिकम् सही है, अतः केवल यह विकल्प अपूर्ण है।"],"topic":"Sanskrit authors and works","level":2,"mode":"standard"},{"q":"Who is the author of the Sanskrit play 'Abhijnanashakuntalam'?","q_hi":"संस्कृत नाटक 'अभिज्ञानशाकुन्तलम्' के रचयिता कौन हैं?","o":["Kalidasa","Bhavabhuti","Banabhatta","Shudraka"],"o_hi":["कालिदास","भवभूति","बाणभट्ट","शूद्रक"],"a":0,"exp":"Abhijnanashakuntalam is a famous play written by Kalidasa. It is one of the greatest works of Sanskrit literature.","exp_hi":"अभिज्ञानशाकुन्तलम् कालिदास द्वारा रचित प्रसिद्ध नाटक है। यह संस्कृत साहित्य की सर्वश्रेष्ठ कृतियों में से एक है।","why":["भवभूति ने 'उत्तररामचरित' और 'महावीरचरित' लिखा, 'अभिज्ञानशाकुन्तलम्' नहीं।","बाणभट्ट ने 'कादम्बरी' और 'हर्षचरित' लिखा, जो गद्य कृतियाँ हैं।","शूद्रक ने 'मृच्छकटिकम्' लिखा, 'अभिज्ञानशाकुन्तलम्' नहीं।"],"topic":"Sanskrit literature - authors","level":1,"mode":"standard"},{"q":"Which of the following is a Sanskrit Mahakavya (epic) written by Kalidasa?","q_hi":"निम्नलिखित में से कौन सा कालिदास द्वारा रचित संस्कृत महाकाव्य है?","o":["Raghuvamsha","Kiratarjuniya","Shishupalavadha","Bhattikavya"],"o_hi":["रघुवंशम्","किरातार्जुनीयम्","शिशुपालवधम्","भट्टिकाव्यम्"],"a":0,"exp":"Raghuvamsha is a Mahakavya by Kalidasa, describing the lineage of Lord Rama.","exp_hi":"रघुवंशम् कालिदास का महाकाव्य है, जिसमें भगवान राम की वंशावली का वर्णन है।","why":["किरातार्जुनीयम् भारवि द्वारा रचित है, कालिदास द्वारा नहीं।","शिशुपालवधम् माघ द्वारा रचित है, कालिदास द्वारा नहीं।","भट्टिकाव्यम् भट्टि द्वारा रचित है, कालिदास द्वारा नहीं।"],"topic":"Sanskrit literature - Mahakavya","level":2,"mode":"standard"},{"q":"Who wrote the Sanskrit grammar text 'Ashtadhyayi'?","q_hi":"संस्कृत व्याकरण ग्रंथ 'अष्टाध्यायी' के रचयिता कौन हैं?","o":["Panini","Patanjali","Katyayana","Vararuchi"],"o_hi":["पाणिनि","पतंजलि","कात्यायन","वररुचि"],"a":0,"exp":"Ashtadhyayi is the foundational Sanskrit grammar text written by Panini, consisting of eight chapters.","exp_hi":"अष्टाध्यायी पाणिनि द्वारा रचित संस्कृत व्याकरण का आधारभूत ग्रंथ है, जिसमें आठ अध्याय हैं।","why":["पतंजलि ने 'महाभाष्य' लिखा, जो अष्टाध्यायी पर भाष्य है, स्वयं अष्टाध्यायी नहीं।","कात्यायन ने 'वार्तिक' लिखे, जो अष्टाध्यायी पर टिप्पणी हैं।","वररुचि ने 'प्राकृतप्रकाश' लिखा, अष्टाध्यायी नहीं।"],"topic":"Sanskrit grammar - Panini","level":1,"mode":"standard"},{"q":"What is the meaning of the Sanskrit phrase 'अहं ब्रह्मास्मि'?","q_hi":"संस्कृत वाक्यांश 'अहं ब्रह्मास्मि' का क्या अर्थ है?","o":["I am Brahman","I am great","I am the world","I am knowledge"],"o_hi":["मैं ब्रह्म हूँ","मैं महान हूँ","मैं संसार हूँ","मैं ज्ञान हूँ"],"a":0,"exp":"'अहं ब्रह्मास्मि' is a Mahavakya from the Upanishads meaning 'I am Brahman' (the ultimate reality).","exp_hi":"'अहं ब्रह्मास्मि' उपनिषदों का महावाक्य है जिसका अर्थ है 'मैं ब्रह्म हूँ' (परम सत्य)।","why":["'मैं महान हूँ' का संस्कृत 'अहं महान् अस्मि' होता है, 'अहं ब्रह्मास्मि' नहीं।","'मैं संसार हूँ' का संस्कृत 'अहं संसारः अस्मि' होता है।","'मैं ज्ञान हूँ' का संस्कृत 'अहं ज्ञानम् अस्मि' होता है।"],"topic":"Sanskrit literature - Upanishads","level":2,"mode":"standard"},{"q":"Which Sanskrit poet is known as the author of 'Buddhacharita', a biography of Buddha?","q_hi":"बुद्ध की जीवनी 'बुद्धचरित' के रचयिता के रूप में कौन संस्कृत कवि जाने जाते हैं?","o":["Ashvaghosha","Kalidasa","Bana","Dandin"],"o_hi":["अश्वघोष","कालिदास","बाण","दण्डी"],"a":0,"exp":"Ashvaghosha wrote Buddhacharita, an epic poem in Sanskrit describing the life of Gautama Buddha.","exp_hi":"अश्वघोष ने बुद्धचरित लिखा, जो गौतम बुद्ध के जीवन का वर्णन करने वाला संस्कृत महाकाव्य है।","why":["कालिदास ने 'रघुवंशम्' आदि लिखे, 'बुद्धचरित' नहीं।","बाण ने 'हर्षचरित' और 'कादम्बरी' लिखी, 'बुद्धचरित' नहीं।","दण्डी ने 'दशकुमारचरित' लिखा, 'बुद्धचरित' नहीं।"],"topic":"Sanskrit literature - authors","level":2,"mode":"standard"},{"q":"Which Vedic text is written in prose and contains rituals, myths and philosophical speculations?","q_hi":"कौन-सा वैदिक ग्रंथ गद्य में लिखा गया है और जिसमें कर्मकांड, मिथक तथा दार्शनिक विचार हैं?","o":["Rigveda","Samaveda","Brahmana","Yajurveda"],"o_hi":["ऋग्वेद","सामवेद","ब्राह्मण","यजुर्वेद"],"a":2,"exp":"The Brahmanas are prose texts that explain the rituals and contain myths and philosophical ideas. They are attached to the Vedas.","exp_hi":"ब्राह्मण ग्रंथ गद्य में हैं जो कर्मकांडों की व्याख्या करते हैं तथा उनमें मिथक और दार्शनिक विचार होते हैं। ये वेदों से जुड़े हैं।","why":["ऋग्वेद मुख्यतः स्तुतियों का संग्रह है, गद्य में नहीं।","सामवेद गाने योग्य मंत्रों का संग्रह है, गद्य नहीं।","यजुर्वेद में यज्ञ के मंत्र और विधियाँ हैं, पर वह पूर्णतः गद्य नहीं है।"],"topic":"Vedic Literature","level":2,"mode":"standard"},{"q":"In Sanskrit grammar, what is the case (vibhakti) of the word 'रामाय' in 'रामाय नमः'?","q_hi":"संस्कृत व्याकरण में 'रामाय नमः' में 'रामाय' किस विभक्ति का रूप है?","o":["प्रथमा (Nominative)","द्वितीया (Accusative)","तृतीया (Instrumental)","चतुर्थी (Dative)"],"o_hi":["प्रथमा","द्वितीया","तृतीया","चतुर्थी"],"a":3,"exp":"'रामाय' is the dative case (चतुर्थी) singular of 'राम'. It is used to show the person to whom something is given or for whom an action is done. 'नमः' takes the dative case.","exp_hi":"'रामाय' 'राम' का चतुर्थी विभक्ति एकवचन है। यह उस व्यक्ति को दर्शाता है जिसे कुछ दिया जाता है या जिसके लिए क्रिया की जाती है। 'नमः' के साथ चतुर्थी का प्रयोग होता है।","why":["प्रथमा विभक्ति कर्ता के लिए होती है, जैसे 'रामः'।","द्वितीया विभक्ति कर्म के लिए होती है, जैसे 'रामम्'।","तृतीया विभक्ति करण के लिए होती है, जैसे 'रामेण'।"],"topic":"Sanskrit Grammar","level":2,"mode":"standard"},{"q":"Which of the following is a famous Sanskrit poem (mahakavya) written by Kalidasa?","q_hi":"निम्नलिखित में से कौन-सा कालिदास द्वारा रचित प्रसिद्ध संस्कृत महाकाव्य है?","o":["रघुवंशम्","किरातार्जुनीयम्","शिशुपालवधम्","नैषधीयचरितम्"],"o_hi":["रघुवंशम्","किरातार्जुनीयम्","शिशुपालवधम्","नैषधीयचरितम्"],"a":0,"exp":"Raghuvamsham is a mahakavya by Kalidasa. It describes the lineage of Lord Rama.","exp_hi":"रघुवंशम् कालिदास का महाकाव्य है। इसमें भगवान राम की वंशावली का वर्णन है।","why":["किरातार्जुनीयम् भारवि द्वारा रचित है।","शिशुपालवधम् माघ द्वारा रचित है।","नैषधीयचरितम् श्रीहर्ष द्वारा रचित है।"],"topic":"Sanskrit Literature","level":1,"mode":"standard"},{"q":"What is the meaning of the Sanskrit suffix 'क्त्वा' (ktva)?","q_hi":"संस्कृत प्रत्यय 'क्त्वा' का क्या अर्थ है?","o":["Having done (perfect participle)","To do (infinitive)","Doer (agent noun)","Will do (future tense)"],"o_hi":["करके (पूर्ण कृदंत)","करने के लिए (तुमुन्)","कर्ता (कर्तृवाचक)","करेगा (भविष्य काल)"],"a":0,"exp":"The suffix 'क्त्वा' forms a perfect participle, meaning 'having done'. For example, 'कृत्वा' means 'having done'.","exp_hi":"'क्त्वा' प्रत्यय पूर्ण कृदंत बनाता है, जिसका अर्थ 'करके' होता है। जैसे 'कृत्वा' का अर्थ 'करके' है।","why":["'तुमुन्' प्रत्यय 'करने के लिए' अर्थ देता है, जैसे 'कर्तुम्'।","'कर्तृ' प्रत्यय कर्ता का बोध कराता है, जैसे 'कर्ता'।","भविष्य काल के लिए 'स्यति' आदि प्रत्यय होते हैं, 'क्त्वा' नहीं।"],"topic":"Sanskrit Grammar","level":2,"mode":"standard"},{"q":"Who wrote the Sanskrit drama 'Mrichchhakatikam'?","q_hi":"संस्कृत नाटक 'मृच्छकटिकम्' के रचयिता कौन हैं?","o":["Kalidasa","Shudraka","Bhavabhuti","Bhasa"],"o_hi":["कालिदास","शूद्रक","भवभूति","भास"],"a":1,"exp":"Mrichchhakatikam (The Little Clay Cart) was written by Shudraka. It is a famous Sanskrit play.","exp_hi":"मृच्छकटिकम् (मिट्टी की छोटी गाड़ी) शूद्रक द्वारा लिखित है। यह एक प्रसिद्ध संस्कृत नाटक है।","why":["कालिदास ने 'अभिज्ञानशाकुन्तलम्' आदि लिखे।","भवभूति ने 'उत्तररामचरित' लिखा।","भास ने 'स्वप्नवासवदत्तम्' लिखा।"],"topic":"Sanskrit Literature","level":1,"mode":"standard"},{"q":"In Sanskrit grammar, what is the correct term for the nominative case (कर्ता कारक)?","q_hi":"संस्कृत व्याकरण में कर्ता कारक का सही नाम क्या है?","o":["प्रथमा विभक्ति","द्वितीया विभक्ति","तृतीया विभक्ति","चतुर्थी विभक्ति"],"o_hi":["प्रथमा विभक्ति","द्वितीया विभक्ति","तृतीया विभक्ति","चतुर्थी विभक्ति"],"a":0,"exp":"The nominative case (कर्ता) is called प्रथमा विभक्ति in Sanskrit. It is used for the subject of a sentence.","exp_hi":"संस्कृत में कर्ता कारक को प्रथमा विभक्ति कहते हैं। यह वाक्य के कर्ता (subject) के लिए प्रयुक्त होती है।","why":["द्वितीया विभक्ति कर्म कारक (accusative) के लिए होती है, कर्ता के लिए नहीं।","तृतीया विभक्ति करण कारक (instrumental) के लिए होती है, कर्ता के लिए नहीं।","चतुर्थी विभक्ति सम्प्रदान कारक (dative) के लिए होती है, कर्ता के लिए नहीं।"],"topic":"Sanskrit grammar - Vibhakti","level":2,"mode":"standard"},{"q":"Which of the following is a Sanskrit poet known for the epic poem 'Kiratarjuniya'?","q_hi":"निम्नलिखित में से कौन 'किरातार्जुनीय' महाकाव्य के रचयिता हैं?","o":["Bharavi","Magha","Shriharsha","Bhatti"],"o_hi":["भारवि","माघ","श्रीहर्ष","भट्टि"],"a":0,"exp":"Kiratarjuniya was composed by Bharavi. It describes the fight between Arjuna and Shiva (disguised as a Kirata).","exp_hi":"किरातार्जुनीय के रचयिता भारवि हैं। इसमें अर्जुन और शिव (किरात वेश में) के युद्ध का वर्णन है।","why":["माघ ने 'शिशुपालवध' लिखा, 'किरातार्जुनीय' नहीं।","श्रीहर्ष ने 'नैषधीयचरित' लिखा, 'किरातार्जुनीय' नहीं।","भट्टि ने 'भट्टिकाव्य' (रावणवध) लिखा, 'किरातार्जुनीय' नहीं।"],"topic":"Sanskrit literature - Epic poetry","level":2,"mode":"standard"},{"q":"Identify the correct sandhi (union) of 'राम + अस्ति'.","q_hi":"'राम + अस्ति' का सही संधि रूप पहचानिए।","o":["रामास्ति","रामस्ति","रामोऽस्ति","रामा अस्ति"],"o_hi":["रामास्ति","रामस्ति","रामोऽस्ति","रामा अस्ति"],"a":0,"exp":"राम + अस्ति = रामास्ति. Here, 'अ' + 'अ' = 'आ' (दीर्घ संधि).","exp_hi":"राम + अस्ति = रामास्ति। यहाँ 'अ' + 'अ' = 'आ' (दीर्घ संधि) होती है।","why":["रामस्ति गलत है क्योंकि 'अ' और 'अ' मिलकर 'आ' बनते हैं, 'अ' नहीं रहता।","रामोऽस्ति गलत है क्योंकि यह 'रामः + अस्ति' का रूप है, जहाँ विसर्ग का 'ओ' होता है।","रामा अस्ति संधि नहीं है, यह अलग-अलग शब्द हैं।"],"topic":"Sanskrit grammar - Sandhi","level":2,"mode":"standard"},{"q":"Which Sanskrit text is a collection of fables and is known as 'Panchatantra'?","q_hi":"'पञ्चतन्त्र' नामक संस्कृत ग्रन्थ किस प्रकार का संग्रह है?","o":["Fables (नीतिकथाएँ)","Vedic hymns (वैदिक सूक्त)","Grammar rules (व्याकरण सूत्र)","Medical treaties (आयुर्वेद ग्रन्थ)"],"o_hi":["नीतिकथाएँ (Fables)","वैदिक सूक्त","व्याकरण सूत्र","आयुर्वेद ग्रन्थ"],"a":0,"exp":"Panchatantra, attributed to Vishnu Sharma, is a collection of fables (animal stories) that teach moral and political wisdom.","exp_hi":"पञ्चतन्त्र, जिसके रचयिता विष्णु शर्मा माने जाते हैं, नीतिकथाओं (पशु कथाओं) का संग्रह है जो नैतिक और राजनीतिक शिक्षा देता है।","why":["वैदिक सूक्त ऋग्वेद आदि में होते हैं, पञ्चतन्त्र में नहीं।","व्याकरण सूत्र पाणिनि के अष्टाध्यायी में हैं, पञ्चतन्त्र में नहीं।","आयुर्वेद ग्रन्थ चरक और सुश्रुत संहिता हैं, पञ्चतन्त्र नहीं।"],"topic":"Sanskrit literature - Fables","level":1,"mode":"standard"},{"q":"In the sentence 'बालकः पुस्तकं पठति', what is the कारक (case) of 'पुस्तकं'?","q_hi":"'बालकः पुस्तकं पठति' वाक्य में 'पुस्तकं' का कारक क्या है?","o":["कर्म (Accusative)","कर्ता (Nominative)","करण (Instrumental)","सम्प्रदान (Dative)"],"o_hi":["कर्म (Accusative)","कर्ता (Nominative)","करण (Instrumental)","सम्प्रदान (Dative)"],"a":0,"exp":"'पुस्तकं' is the object of the verb 'पठति' (reads), so it is in कर्म कारक (accusative case).","exp_hi":"'पुस्तकं' क्रिया 'पठति' (पढ़ता है) का कर्म है, इसलिए यह कर्म कारक (द्वितीया विभक्ति) में है।","why":["कर्ता कारक 'बालकः' है, 'पुस्तकं' नहीं।","करण कारक साधन बताता है, जैसे 'लेखन्या लिखति' में 'लेखन्या'।","सम्प्रदान कारक 'रामाय' आदि में होता है, यहाँ नहीं।"],"topic":"Sanskrit grammar - Karaka","level":2,"mode":"standard"},{"q":"Which one of the following is the correct Sanskrit word for 'teacher'?","q_hi":"निम्नलिखित में से 'शिक्षक' के लिए सही संस्कृत शब्द कौन-सा है?","o":["शिष्यः","आचार्यः","पुस्तकम्","विद्यालयः"],"o_hi":["शिष्यः","आचार्यः","पुस्तकम्","विद्यालयः"],"a":1,"exp":"'आचार्यः' means teacher/preceptor. 'शिष्यः' means student, 'पुस्तकम्' means book, 'विद्यालयः' means school.","exp_hi":"'आचार्यः' का अर्थ शिक्षक/गुरु होता है। 'शिष्यः' का अर्थ विद्यार्थी, 'पुस्तकम्' का अर्थ पुस्तक और 'विद्यालयः' का अर्थ विद्यालय होता है।","why":["'शिष्यः' का अर्थ विद्यार्थी होता है, शिक्षक नहीं।","'पुस्तकम्' का अर्थ पुस्तक होता है, शिक्षक नहीं।","'विद्यालयः' का अर्थ विद्यालय होता है, शिक्षक नहीं।"],"topic":"Sanskrit Vocabulary","level":1,"mode":"standard"},{"q":"Which of the following is a Sanskrit drama written by Bhasa?","q_hi":"निम्नलिखित में से कौन-सा संस्कृत नाटक भास द्वारा रचित है?","o":["मृच्छकटिकम्","स्वप्नवासवदत्तम्","उत्तररामचरितम्","अभिज्ञानशाकुन्तलम्"],"o_hi":["मृच्छकटिकम्","स्वप्नवासवदत्तम्","उत्तररामचरितम्","अभिज्ञानशाकुन्तलम्"],"a":1,"exp":"'स्वप्नवासवदत्तम्' is a play by Bhasa. It is based on the story of King Udayana.","exp_hi":"'स्वप्नवासवदत्तम्' भास का नाटक है। यह राजा उदयन की कथा पर आधारित है।","why":["'मृच्छकटिकम्' शूद्रक द्वारा रचित है, भास द्वारा नहीं।","'उत्तररामचरितम्' भवभूति द्वारा रचित है, भास द्वारा नहीं।","'अभिज्ञानशाकुन्तलम्' कालिदास द्वारा रचित है, भास द्वारा नहीं।"],"topic":"Sanskrit Literature","level":2,"mode":"standard"},{"q":"Identify the correct Sanskrit sentence: 'The boy reads a book.'","q_hi":"सही संस्कृत वाक्य पहचानिए: 'बालकः पुस्तकं पठति।'","o":["बालकः पुस्तकं पठति।","बालकं पुस्तकः पठति।","बालकः पुस्तकः पठति।","बालकं पुस्तकं पठति।"],"o_hi":["बालकः पुस्तकं पठति।","बालकं पुस्तकः पठति।","बालकः पुस्तकः पठति।","बालकं पुस्तकं पठति।"],"a":0,"exp":"In Sanskrit, the subject 'बालकः' (boy) is in nominative case, and the object 'पुस्तकम्' (book) is in accusative case. The verb 'पठति' agrees with the subject.","exp_hi":"संस्कृत में कर्ता 'बालकः' प्रथमा विभक्ति में और कर्म 'पुस्तकम्' द्वितीया विभक्ति में होता है। क्रिया 'पठति' कर्ता के अनुसार होती है।","why":["'बालकं' द्वितीया विभक्ति है, जो कर्म के लिए होती है, कर्ता के लिए नहीं।","'पुस्तकः' पुल्लिङ्ग प्रथमा विभक्ति है, जबकि 'पुस्तक' नपुंसकलिङ्ग है।","'बालकं' और 'पुस्तकं' दोनों द्वितीया विभक्ति में हैं, जो व्याकरणिक रूप से अशुद्ध है।"],"topic":"Sanskrit Grammar","level":2,"mode":"standard"},{"q":"Who among the following is known as the author of 'Ramcharitmanas'?","q_hi":"निम्नलिखित में से 'रामचरितमानस' के रचयिता कौन हैं?","o":["वाल्मीकिः","तुलसीदासः","कालिदासः","वेदव्यासः"],"o_hi":["वाल्मीकिः","तुलसीदासः","कालिदासः","वेदव्यासः"],"a":1,"exp":"'Ramcharitmanas' was written by Tulsidas in Awadhi, not in Sanskrit. Valmiki wrote the Sanskrit 'Ramayana'.","exp_hi":"'रामचरितमानस' की रचना तुलसीदास ने अवधी में की थी, संस्कृत में नहीं। वाल्मीकि ने संस्कृत 'रामायण' लिखी।","why":["वाल्मीकि ने संस्कृत 'रामायण' लिखी, 'रामचरितमानस' नहीं।","कालिदास ने 'रघुवंशम्' आदि लिखे, 'रामचरितमानस' नहीं।","वेदव्यास ने 'महाभारत' लिखा, 'रामचरितमानस' नहीं।"],"topic":"Sanskrit Literature","level":1,"mode":"standard"}]}]/*__DATA_END__*/);
